from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")
    distinct_strings = []
    current_group = ""

    for char in paren_string:
        if char == "(":
            if current_group:
                distinct_strings.append(current_group)
            current_group = "("
        elif char == ")":
            current_group += ")"
            distinct_strings.append(current_group)
            current_group = ""

    if current_group:
        distinct_strings.append(current_group)

    return distinct_strings

